src='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    positions = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                positions.setdefault(color, []).append((r, c))

    frames = []
    for color, cells in positions.items():
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        border = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if all(grid[r][c] == color for r, c in border) and all(
            grid[r][c] == 0 for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)
        ):
            frames.append((color, r0, r1, c0, c1))

    frame_colors = {f[0] for f in frames}
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] and grid[r][c] not in frame_colors)
    out = [[0] * w for _ in range(h)]
    for _, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = grid[r][c]
        interior = [(r, c) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)
                    if (r + c) % 2 == 0]
        target = len(interior)
        candidates = [color for color, count in counts.items() if count == target]
        if candidates:
            fill = candidates[0]
            for r, c in interior:
                out[r][c] = fill
    return out
'''
